/**
 * @fileoverview coingecko_get_market_chart — historical price, market cap, and
 * volume time series. Two modes: recent (last N days, auto-granularity) or range
 * (explicit Unix-second from/to). Timestamps are MILLISECONDS.
 * @module src/mcp-server/tools/definitions/get-market-chart.tool
 */

import { tool, z } from '@cyanheads/mcp-ts-core';
import { JsonRpcErrorCode } from '@cyanheads/mcp-ts-core/errors';

import { getCoinGeckoService } from '@/services/coingecko/coingecko-service.js';
import { COINGECKO_SERVICE_ERRORS } from '@/services/coingecko/error-contracts.js';
import { type ChartGranularity, COINGECKO_ATTRIBUTION } from '@/services/coingecko/types.js';

/** Granularity CoinGecko auto-applies by span (recent mode). */
function recentGranularity(days: number | 'max'): ChartGranularity {
  if (days === 'max') return 'daily';
  if (days <= 1) return 'minutely';
  if (days <= 90) return 'hourly';
  return 'daily';
}

/** Granularity by span for an explicit range (same thresholds as recent). */
function rangeGranularity(fromSec: number, toSec: number): ChartGranularity {
  const days = (toSec - fromSec) / 86_400;
  if (days <= 1) return 'minutely';
  if (days <= 90) return 'hourly';
  return 'daily';
}

const PointSchema = z
  .object({
    t: z.number().describe('Timestamp in Unix MILLISECONDS (note: /simple/price uses seconds).'),
    value: z
      .number()
      .describe('Value at this timestamp (price, market cap, or volume in vs_currency).'),
  })
  .describe('One time-series point.');

export const getMarketChartTool = tool('coingecko_get_market_chart', {
  title: 'coingecko-mcp-server: get market chart',
  description:
    'Historical price, market cap, and volume time series for a coin. Two modes: recent (last N days; granularity auto-scales — ≤1 day → ~5-min, 2–90 → hourly, >90 → daily) or range (explicit Unix-second from/to). Returns timestamped point arrays. Use for trend/charting questions, not the current snapshot (use coingecko_get_prices for that). The id must be a CoinGecko slug (resolve tickers with coingecko_search_coins). Chart timestamps are milliseconds.',
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: true },

  errors: [
    {
      reason: 'coin_not_found',
      code: JsonRpcErrorCode.NotFound,
      when: 'Upstream returned 404 for the slug — it is not a recognized CoinGecko id.',
      recovery:
        'Resolve the slug via coingecko_search_coins first — IDs are slugs (bitcoin), not tickers (BTC).',
    },
    {
      reason: 'invalid_range',
      code: JsonRpcErrorCode.ValidationError,
      when: 'Mode/parameter mismatch — range mode without both from and to, or recent mode without days.',
      recovery: 'For mode=recent pass days; for mode=range pass both from and to as Unix seconds.',
    },
    ...COINGECKO_SERVICE_ERRORS,
  ],

  input: z.object({
    id: z
      .string()
      .min(1)
      .describe(
        'CoinGecko slug (e.g. "bitcoin"). Not a ticker — resolve with coingecko_search_coins.',
      ),
    vs_currency: z
      .string()
      .min(1)
      .default('usd')
      .describe('Currency to denominate the series in. Single currency; defaults to "usd".'),
    mode: z
      .enum(['recent', 'range'])
      .default('recent')
      .describe(
        'recent: last N days (use days). range: explicit window (use from and to as Unix seconds).',
      ),
    days: z
      .union([
        z.number().int().min(1).describe('Number of days back from now.'),
        z.literal('max').describe('Full available history.'),
      ])
      .optional()
      .describe(
        'recent mode: number of days back, or "max" for full history. Required when mode=recent.',
      ),
    from: z
      .number()
      .int()
      .optional()
      .describe('range mode: start time as a Unix timestamp in SECONDS. Required when mode=range.'),
    to: z
      .number()
      .int()
      .optional()
      .describe('range mode: end time as a Unix timestamp in SECONDS. Required when mode=range.'),
  }),

  output: z.object({
    id: z.string().describe('CoinGecko slug the series is for.'),
    vsCurrency: z.string().describe('Currency the series is denominated in.'),
    granularity: z
      .enum(['minutely', 'hourly', 'daily'])
      .describe(
        'Point spacing CoinGecko applied for this span (computed from the requested range).',
      ),
    pointCount: z.number().describe('Number of price points returned.'),
    prices: z.array(PointSchema).describe(`Price series. ${COINGECKO_ATTRIBUTION}.`),
    marketCaps: z.array(PointSchema).describe('Market-cap series over the same window.'),
    volumes: z.array(PointSchema).describe('Volume series over the same window.'),
    attribution: z.string().describe('Required data-source attribution.'),
  }),

  async handler(input, ctx) {
    ctx.log.info('coingecko_get_market_chart', { id: input.id, mode: input.mode });
    const svc = getCoinGeckoService();

    let chart: Awaited<ReturnType<typeof svc.marketChart>>;
    let granularity: ChartGranularity;

    if (input.mode === 'range') {
      if (input.from == null || input.to == null) {
        throw ctx.fail('invalid_range', 'mode=range requires both from and to (Unix seconds).', {
          ...ctx.recoveryFor('invalid_range'),
        });
      }
      granularity = rangeGranularity(input.from, input.to);
      chart = await svc.marketChartRange(input.id, input.vs_currency, input.from, input.to, ctx);
    } else {
      if (input.days == null) {
        throw ctx.fail('invalid_range', 'mode=recent requires days.', {
          ...ctx.recoveryFor('invalid_range'),
        });
      }
      granularity = recentGranularity(input.days);
      chart = await svc.marketChart(input.id, input.vs_currency, input.days, ctx);
    }

    if (!chart) {
      throw ctx.fail('coin_not_found', `Coin "${input.id}" not found.`, {
        id: input.id,
        ...ctx.recoveryFor('coin_not_found'),
      });
    }

    return {
      id: input.id,
      vsCurrency: input.vs_currency,
      granularity,
      pointCount: chart.prices.length,
      prices: chart.prices,
      marketCaps: chart.marketCaps,
      volumes: chart.volumes,
      attribution: COINGECKO_ATTRIBUTION,
    };
  },

  // Summarize rather than dump every point — long series overflow context.
  format: (result) => {
    const lines = [
      `## ${result.id} — market chart (${result.vsCurrency})`,
      `**Granularity:** ${result.granularity} | **Points:** ${result.pointCount}`,
    ];
    const summarize = (label: string, pts: { t: number; value: number }[]) => {
      if (pts.length === 0) {
        lines.push(`**${label}:** (no points)`);
        return;
      }
      const first = pts[0];
      const last = pts[pts.length - 1];
      lines.push(
        `**${label}:** first ${first?.value} @ ${first?.t}ms → last ${last?.value} @ ${last?.t}ms`,
      );
    };
    summarize('Prices', result.prices);
    summarize('Market caps', result.marketCaps);
    summarize('Volumes', result.volumes);
    lines.push('\n_Timestamps are Unix milliseconds._');
    lines.push(`\n_${result.attribution}_`);
    return [{ type: 'text', text: lines.join('\n') }];
  },
});

/**
 * @fileoverview coingecko_get_prices — current price and core market stats for
 * one or more coins in one or more currencies. Diffs requested-vs-returned ids
 * to surface silent misses (a wrong slug returns 200-empty upstream, not an error).
 * @module src/mcp-server/tools/definitions/get-prices.tool
 */

import { tool, z } from '@cyanheads/mcp-ts-core';
import { JsonRpcErrorCode } from '@cyanheads/mcp-ts-core/errors';

import { getCoinGeckoService } from '@/services/coingecko/coingecko-service.js';
import { COINGECKO_SERVICE_ERRORS } from '@/services/coingecko/error-contracts.js';
import { COINGECKO_ATTRIBUTION } from '@/services/coingecko/types.js';

export const getPricesTool = tool('coingecko_get_prices', {
  title: 'coingecko-mcp-server: get prices',
  description:
    'Current price and core market stats (market cap, 24h volume, 24h change) for one or more coins in one or more fiat/crypto currencies. Batch-friendly — pass a whole portfolio in one call (up to 250 ids). IDs must be CoinGecko slugs (bitcoin, ethereum), not tickers; resolve unknown tickers with coingecko_search_coins first. Any requested ids that returned no data are reported in the missing field (a wrong slug yields a silent upstream miss, not an error), so a typo reads as "unresolved", not "nonexistent".',
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: true },

  errors: [
    {
      reason: 'all_missing',
      code: JsonRpcErrorCode.NotFound,
      when: 'No requested ID returned data — every slug was unknown or the upstream response was empty.',
      recovery:
        'Resolve tickers to slugs with coingecko_search_coins, then retry with the returned ids.',
    },
    ...COINGECKO_SERVICE_ERRORS,
  ],

  input: z.object({
    ids: z
      .array(z.string().min(1))
      .min(1)
      .max(250)
      .describe(
        'CoinGecko slugs to price (e.g. ["bitcoin","ethereum"]). Not tickers — resolve with coingecko_search_coins. Up to 250 per call.',
      ),
    vs_currencies: z
      .array(z.string().min(1))
      .min(1)
      .default(['usd'])
      .describe('Currency codes to price against (e.g. ["usd","eur","btc"]). Defaults to ["usd"].'),
  }),

  output: z.object({
    prices: z
      .array(
        z
          .object({
            id: z.string().describe('CoinGecko slug.'),
            currency: z.string().describe('Currency code this row is denominated in.'),
            price: z.number().describe('Current price in the row currency.'),
            marketCap: z
              .number()
              .optional()
              .describe('Market capitalization in the row currency, when available.'),
            vol24h: z
              .number()
              .optional()
              .describe('24-hour trading volume in the row currency, when available.'),
            change24h: z
              .number()
              .optional()
              .describe('24-hour price change as a percentage, when available.'),
          })
          .describe('Price and stats for one coin in one currency.'),
      )
      .describe(`One row per (id, currency) that returned a price. ${COINGECKO_ATTRIBUTION}.`),
    missing: z
      .array(z.string())
      .describe(
        'Requested ids absent from the response (unknown slug or upstream silent miss). Re-resolve these with coingecko_search_coins. Empty when all ids resolved.',
      ),
    lastUpdatedAtUnixSec: z
      .number()
      .optional()
      .describe(
        'Upstream last-updated time as a Unix timestamp in seconds (note: market-chart timestamps are milliseconds).',
      ),
    attribution: z.string().describe('Required data-source attribution.'),
  }),

  enrichment: {
    notice: z
      .string()
      .optional()
      .describe(
        'Guidance when some requested ids returned no data — lists the missing ids and how to recover.',
      ),
  },

  async handler(input, ctx) {
    ctx.log.info('coingecko_get_prices', {
      idCount: input.ids.length,
      currencies: input.vs_currencies,
    });
    const result = await getCoinGeckoService().simplePrice(input.ids, input.vs_currencies, ctx);

    if (result.missing.length === input.ids.length) {
      throw ctx.fail(
        'all_missing',
        `None of the ${input.ids.length} requested id(s) returned data.`,
        { missing: result.missing, ...ctx.recoveryFor('all_missing') },
      );
    }

    // Currencies that returned no row for ANY resolved coin were silently dropped
    // upstream (an unsupported vs_currency yields no key rather than an error) —
    // disclose them so a bad currency code isn't mistaken for a flat market.
    const returnedCurrencies = new Set(result.rows.map((r) => r.currency));
    const droppedCurrencies = input.vs_currencies.filter((c) => !returnedCurrencies.has(c));

    const notices: string[] = [];
    if (result.missing.length > 0) {
      notices.push(
        `No data for id(s): ${result.missing.join(', ')}. These slugs are unknown to CoinGecko or returned a silent miss — re-resolve them with coingecko_search_coins (IDs are slugs like "bitcoin", not tickers like "BTC").`,
      );
    }
    if (droppedCurrencies.length > 0) {
      notices.push(
        `No data for currenc(ies): ${droppedCurrencies.join(', ')}. CoinGecko silently drops unsupported currency codes — check the code (e.g. "usd", "eur", "btc").`,
      );
    }
    if (notices.length > 0) {
      ctx.enrich.notice(notices.join(' '));
    }

    return {
      prices: result.rows,
      missing: result.missing,
      ...(result.lastUpdatedAt !== undefined && { lastUpdatedAtUnixSec: result.lastUpdatedAt }),
      attribution: COINGECKO_ATTRIBUTION,
    };
  },

  format: (result) => {
    const lines = ['## Prices'];
    for (const r of result.prices) {
      const parts = [`**${r.id}** (${r.currency}): ${r.price}`];
      if (r.marketCap != null) parts.push(`cap ${r.marketCap}`);
      if (r.vol24h != null) parts.push(`vol24h ${r.vol24h}`);
      if (r.change24h != null) parts.push(`24h ${r.change24h}%`);
      lines.push(`- ${parts.join(' · ')}`);
    }
    if (result.missing.length > 0) {
      lines.push(`\n**Missing (no data):** ${result.missing.join(', ')}`);
    }
    if (result.lastUpdatedAtUnixSec != null) {
      lines.push(`\n_Last updated: ${result.lastUpdatedAtUnixSec} (Unix seconds)_`);
    }
    lines.push(`\n_${result.attribution}_`);
    return [{ type: 'text', text: lines.join('\n') }];
  },
});

