/**
 * @fileoverview Low-level HTTP client for the CoinGecko REST API v3. Builds URLs,
 * attaches the optional Demo-tier API key header, and exposes single-attempt
 * fetch calls. Retry logic lives in `CoinGeckoService`.
 *
 * `fetchWithTimeout` throws a classified `McpError` on any non-OK status (it only
 * returns the `Response` when `response.ok`), so this client keys off the THROWN
 * error's code, not a status check on a response it never receives. It maps the
 * three probe-confirmed error envelopes:
 *   - 404 `{"error":"coin not found"}` → NotFound. `getJsonOrNull` swallows this to
 *     `null` so the calling tool can throw a typed `coin_not_found` /
 *     `unknown_category`; `getJson` rethrows it enriched.
 *   - 429 `{"status":{"error_code":429,...}}` → RateLimited (retryable). Enriched
 *     with the `rate_limited` reason + recovery hint so the contract reaches the wire.
 *   - 200 `{}` silent miss on /simple/price → NOT an error; passed through for the
 *     tool to diff requested-vs-returned ids.
 * @module src/services/coingecko/api-client
 */

import { JsonRpcErrorCode, McpError, serviceUnavailable } from '@cyanheads/mcp-ts-core/errors';
import { fetchWithTimeout, requestContextService } from '@cyanheads/mcp-ts-core/utils';

import { type CoinGeckoServiceReason, recoveryFor } from './error-contracts.js';
import { COINGECKO_API_BASE } from './types.js';

const USER_AGENT = 'coingecko-mcp-server (+https://github.com/cyanheads/coingecko-mcp-server)';

export interface CoinGeckoApiClientConfig {
  /** Optional Demo API key → sent as x-cg-demo-api-key. */
  apiKey?: string;
  timeoutMs: number;
}

/** Query param values accepted by the client (joined/encoded internally). */
export type QueryValue = string | number | boolean | undefined;

/** Low-level HTTP client for CoinGecko. Single-attempt — retries live upstream. */
export class CoinGeckoApiClient {
  constructor(private readonly config: CoinGeckoApiClientConfig) {}

  private buildUrl(path: string, query?: Record<string, QueryValue>): string {
    const params = new URLSearchParams();
    if (query) {
      for (const [key, value] of Object.entries(query)) {
        if (value !== undefined) params.set(key, String(value));
      }
    }
    const qs = params.toString();
    return `${COINGECKO_API_BASE}${path}${qs ? `?${qs}` : ''}`;
  }

  private headers(): Record<string, string> {
    const headers: Record<string, string> = {
      Accept: 'application/json',
      'User-Agent': USER_AGENT,
    };
    if (this.config.apiKey) headers['x-cg-demo-api-key'] = this.config.apiKey;
    return headers;
  }

  /**
   * GET a JSON endpoint. A non-OK status throws (via `fetchWithTimeout`) and is
   * rethrown here enriched with a contract `reason` + recovery hint. Use for
   * endpoints where any non-2xx is a genuine failure to surface.
   */
  async getJson<T>(
    operation: string,
    path: string,
    query: Record<string, QueryValue> | undefined,
    signal: AbortSignal | undefined,
  ): Promise<T> {
    const response = await this.fetch(operation, path, query, signal);
    return this.parseJson<T>(response, path);
  }

  /**
   * GET a JSON endpoint, returning `null` on HTTP 404 instead of throwing. Used by
   * coin-detail, market-chart, and the category-filtered markets path so the tool
   * can throw its own typed reason (`coin_not_found` / `unknown_category`) with
   * slug-resolution recovery rather than a generic NotFound. Other non-OK statuses
   * still throw (enriched).
   */
  async getJsonOrNull<T>(
    operation: string,
    path: string,
    query: Record<string, QueryValue> | undefined,
    signal: AbortSignal | undefined,
  ): Promise<T | null> {
    try {
      const response = await this.fetch(operation, path, query, signal, [404]);
      return await this.parseJson<T>(response, path);
    } catch (error: unknown) {
      if (error instanceof McpError && error.code === JsonRpcErrorCode.NotFound) return null;
      throw error;
    }
  }

  /**
   * Single fetch attempt. `fetchWithTimeout` throws a classified `McpError` on any
   * non-OK status; we enrich it with the contract `reason` + recovery so clients
   * get the same actionable hint a handler-level `ctx.fail` would carry. A raw
   * network/timeout failure (no `McpError`) maps to `upstream_unreachable`.
   * `expectedStatuses` lists statuses the caller treats as an expected outcome —
   * they still throw unchanged but log at debug instead of error.
   */
  private async fetch(
    operation: string,
    path: string,
    query: Record<string, QueryValue> | undefined,
    signal: AbortSignal | undefined,
    expectedStatuses?: number[],
  ): Promise<Response> {
    const url = this.buildUrl(path, query);
    const ctx = requestContextService.createRequestContext({
      operation,
      additionalContext: { path },
    });
    try {
      return await fetchWithTimeout(url, this.config.timeoutMs, ctx, {
        headers: this.headers(),
        ...(signal && { signal }),
        ...(expectedStatuses && { expectedStatuses }),
      });
    } catch (error: unknown) {
      if (error instanceof McpError) throw this.enrich(error, path);
      const msg = error instanceof Error ? error.message : String(error);
      throw serviceUnavailable(
        `CoinGecko request failed: ${msg}`,
        { reason: 'upstream_unreachable', path, ...recoveryFor('upstream_unreachable') },
        { cause: error },
      );
    }
  }

  /**
   * Attach a contract `reason` + recovery hint to a `fetchWithTimeout` error,
   * preserving its status-derived code, message, captured body, and `Retry-After`.
   * 429 → `rate_limited`; everything else (5xx, timeout, unexpected) →
   * `upstream_unreachable`. A NotFound passes through unchanged — `getJsonOrNull`
   * swallows it to `null` and `getJson`'s callers don't expect a 404, so leaving
   * its code intact keeps auto-classification honest.
   */
  private enrich(error: McpError, path: string): McpError {
    const reason: CoinGeckoServiceReason =
      error.code === JsonRpcErrorCode.RateLimited ? 'rate_limited' : 'upstream_unreachable';
    const data = {
      ...(error.data as Record<string, unknown> | undefined),
      path,
      reason,
      ...recoveryFor(reason),
    };
    return new McpError(error.code, error.message, data, { cause: error });
  }

  /**
   * Parse a 2xx body as JSON. An HTML body on a 200 (an edge form of throttling /
   * an upstream error page) is reclassified as transient rather than a
   * non-retryable SerializationError.
   */
  private async parseJson<T>(response: Response, path: string): Promise<T> {
    const text = await response.text();
    if (/^\s*<(!doctype\s+html|html[\s>])/i.test(text)) {
      throw serviceUnavailable(
        'CoinGecko returned an HTML body instead of JSON — likely rate-limited.',
        { reason: 'upstream_unreachable', path, ...recoveryFor('upstream_unreachable') },
      );
    }
    try {
      return JSON.parse(text) as T;
    } catch (error: unknown) {
      throw serviceUnavailable(
        'CoinGecko returned a non-JSON body.',
        { reason: 'invalid_response', path, ...recoveryFor('invalid_response') },
        { cause: error },
      );
    }
  }
}

/**
 * @fileoverview CoinGecko REST API v3 service. One method per endpoint the tools
 * need; each wraps the full fetch+parse pipeline in `withRetry` (transient codes
 * — 429/5xx/timeout — retried with calibrated backoff). Normalizes probe-verified
 * raw shapes into honest domain types, preserving upstream absence rather than
 * fabricating values. Init/accessor pattern; initialized from `setup()`.
 * @module src/services/coingecko/coingecko-service
 */

import type { Context } from '@cyanheads/mcp-ts-core';
import { notFound } from '@cyanheads/mcp-ts-core/errors';
import { logger, requestContextService, withRetry } from '@cyanheads/mcp-ts-core/utils';

import { getServerConfig } from '@/config/server-config.js';
import { CoinGeckoApiClient } from './api-client.js';
import type {
  Category,
  CoinDetail,
  GlobalMarket,
  MarketChartResult,
  MarketCoin,
  RawCategory,
  RawCoinDetail,
  RawGlobalResponse,
  RawMarketChart,
  RawMarketCoin,
  RawSearchResponse,
  RawSimplePrice,
  RawTrendingResponse,
  SearchCoin,
  SimplePriceResult,
  TrendingResult,
} from './types.js';

/** Rate-limited upstream → back off on the longer end (per the design's resilience table). */
const BASE_DELAY_MS = 1500;
const TIMEOUT_MS = 15_000;
const MAX_RETRIES = 3;

/** Reads `vs_currency` from a per-currency map, treating null as absent. */
function pickCurrency(
  map: Record<string, number | null> | undefined,
  currency: string,
): number | undefined {
  const v = map?.[currency];
  return typeof v === 'number' ? v : undefined;
}

function pickDate(
  map: Record<string, string | null> | undefined,
  currency: string,
): string | undefined {
  const v = map?.[currency];
  return typeof v === 'string' && v.length > 0 ? v : undefined;
}

/** Numeric-or-undefined coercion: null/undefined collapse to undefined. */
function num(v: number | null | undefined): number | undefined {
  return typeof v === 'number' ? v : undefined;
}

function str(v: string | null | undefined): string | undefined {
  return typeof v === 'string' && v.length > 0 ? v : undefined;
}

function toPoints(pairs: [number, number][] | undefined): { t: number; value: number }[] {
  return (pairs ?? []).map(([t, value]) => ({ t, value }));
}

/**
 * Strip keys whose value is `undefined`, returning a type whose optional
 * properties are exact (no `| undefined`) — the honest "omit absent" shape under
 * `exactOptionalPropertyTypes`. Lets normalizers build flat records with
 * undefined-able values and drop the absent ones in one pass.
 */
function omitUndefined<T extends Record<string, unknown>>(
  obj: T,
): { [K in keyof T]?: Exclude<T[K], undefined> } {
  const out: Record<string, unknown> = {};
  for (const [k, v] of Object.entries(obj)) {
    if (v !== undefined) out[k] = v;
  }
  return out as { [K in keyof T]?: Exclude<T[K], undefined> };
}

/** Service facade over the CoinGecko v3 REST API. */
export class CoinGeckoService {
  constructor(private readonly client: CoinGeckoApiClient) {}

  private retry<T>(operation: string, ctx: Context, fn: () => Promise<T>): Promise<T> {
    return withRetry(fn, {
      operation,
      baseDelayMs: BASE_DELAY_MS,
      maxRetries: MAX_RETRIES,
      signal: ctx.signal,
    });
  }

  /** `/search` — resolve a name/ticker to ranked slug candidates. */
  async search(query: string, ctx: Context): Promise<SearchCoin[]> {
    const raw = await this.retry('coingecko.search', ctx, () =>
      this.client.getJson<RawSearchResponse>('coingecko.search', '/search', { query }, ctx.signal),
    );
    return (raw.coins ?? []).map((c) => ({
      id: c.id,
      symbol: c.symbol,
      name: c.name,
      ...omitUndefined({
        marketCapRank: typeof c.market_cap_rank === 'number' ? c.market_cap_rank : undefined,
        thumb: str(c.thumb),
      }),
    }));
  }

  /**
   * `/simple/price` — batch current price for ids × currencies. Diffs requested
   * ids against returned keys to populate `missing` (silent-miss detection): a
   * bad slug is omitted entirely upstream, so absence here is the only signal.
   */
  async simplePrice(
    ids: string[],
    vsCurrencies: string[],
    ctx: Context,
  ): Promise<SimplePriceResult> {
    const raw = await this.retry('coingecko.simplePrice', ctx, () =>
      this.client.getJson<RawSimplePrice>(
        'coingecko.simplePrice',
        '/simple/price',
        {
          ids: ids.join(','),
          vs_currencies: vsCurrencies.join(','),
          include_market_cap: true,
          include_24hr_vol: true,
          include_24hr_change: true,
          include_last_updated_at: true,
        },
        ctx.signal,
      ),
    );

    const rows: SimplePriceResult['rows'] = [];
    const returnedIds = new Set<string>();
    let lastUpdatedAt: number | undefined;

    for (const [id, entry] of Object.entries(raw)) {
      if (!entry || typeof entry !== 'object') continue;
      returnedIds.add(id);
      if (typeof entry.last_updated_at === 'number') lastUpdatedAt = entry.last_updated_at;
      for (const currency of vsCurrencies) {
        const price = entry[currency];
        if (typeof price !== 'number') continue; // bad currency drops its key silently
        rows.push({
          id,
          currency,
          price,
          ...(typeof entry[`${currency}_market_cap`] === 'number' && {
            marketCap: entry[`${currency}_market_cap`],
          }),
          ...(typeof entry[`${currency}_24h_vol`] === 'number' && {
            vol24h: entry[`${currency}_24h_vol`],
          }),
          ...(typeof entry[`${currency}_24h_change`] === 'number' && {
            change24h: entry[`${currency}_24h_change`],
          }),
        });
      }
    }

    const missing = ids.filter((id) => !returnedIds.has(id));
    return { rows, missing, ...(lastUpdatedAt !== undefined && { lastUpdatedAt }) };
  }

  /**
   * `/coins/markets` — ranked market table (one page). Returns `null` only when a
   * `category` was supplied and upstream answered 404 (an unrecognized category
   * slug — CoinGecko 404s on a bad category rather than returning an empty array),
   * so the tool can throw a typed `unknown_category`. Without a category, a 404 is
   * not expected and bubbles as a normal error.
   */
  async coinsMarkets(
    params: {
      vsCurrency: string;
      order: string;
      category?: string;
      page: number;
      perPage: number;
    },
    ctx: Context,
  ): Promise<MarketCoin[] | null> {
    const query = {
      vs_currency: params.vsCurrency,
      order: params.order,
      ...(params.category && { category: params.category }),
      page: params.page,
      per_page: params.perPage,
      price_change_percentage: '1h,24h,7d',
      sparkline: false,
    };
    const raw = await this.retry('coingecko.coinsMarkets', ctx, () =>
      params.category
        ? this.client.getJsonOrNull<RawMarketCoin[]>(
            'coingecko.coinsMarkets',
            '/coins/markets',
            query,
            ctx.signal,
          )
        : this.client.getJson<RawMarketCoin[]>(
            'coingecko.coinsMarkets',
            '/coins/markets',
            query,
            ctx.signal,
          ),
    );
    if (raw === null) return null;
    return raw.map(
      (c): MarketCoin => ({
        id: c.id,
        symbol: c.symbol,
        name: c.name,
        ...omitUndefined({
          currentPrice: num(c.current_price),
          marketCap: num(c.market_cap),
          marketCapRank: num(c.market_cap_rank),
          totalVolume: num(c.total_volume),
          high24h: num(c.high_24h),
          low24h: num(c.low_24h),
          priceChangePercentage24h: num(
            c.price_change_percentage_24h_in_currency ?? c.price_change_percentage_24h,
          ),
          priceChangePercentage1h: num(c.price_change_percentage_1h_in_currency),
          priceChangePercentage7d: num(c.price_change_percentage_7d_in_currency),
          circulatingSupply: num(c.circulating_supply),
          totalSupply: num(c.total_supply),
          maxSupply: num(c.max_supply),
          ath: num(c.ath),
          athDate: str(c.ath_date),
          atl: num(c.atl),
          atlDate: str(c.atl_date),
        }),
      }),
    );
  }

  /**
   * `/coins/{id}` — deep profile. Returns `null` on 404 (unknown slug) so the
   * tool can throw a typed `coin_not_found`. `currency` selects the scalar to
   * pull from the per-currency `market_data` maps.
   */
  async coinDetail(id: string, currency: string, ctx: Context): Promise<CoinDetail | null> {
    const raw = await this.retry('coingecko.coinDetail', ctx, () =>
      this.client.getJsonOrNull<RawCoinDetail>(
        'coingecko.coinDetail',
        `/coins/${encodeURIComponent(id)}`,
        {
          localization: false,
          tickers: false,
          market_data: true,
          community_data: true,
          developer_data: true,
          sparkline: false,
        },
        ctx.signal,
      ),
    );
    if (!raw) return null;

    const md = raw.market_data;
    const links = raw.links;
    const dev = raw.developer_data;
    const comm = raw.community_data;

    const categories = (raw.categories ?? []).filter(
      (c): c is string => typeof c === 'string' && c.length > 0,
    );
    const homepage = (links?.homepage ?? []).filter((u) => typeof u === 'string' && u.length > 0);
    const repos = [
      ...(links?.repos_url?.github ?? []),
      ...(links?.repos_url?.bitbucket ?? []),
    ].filter((u) => typeof u === 'string' && u.length > 0);

    const athPrice = pickCurrency(md?.ath, currency);
    const atlPrice = pickCurrency(md?.atl, currency);
    const athDate = pickDate(md?.ath_date, currency);
    const atlDate = pickDate(md?.atl_date, currency);

    return {
      id: raw.id,
      symbol: raw.symbol,
      name: raw.name,
      profile: {
        categories,
        ...omitUndefined({
          description: str(raw.description?.en),
          genesisDate: str(raw.genesis_date),
          hashingAlgorithm: str(raw.hashing_algorithm),
          countryOrigin: str(raw.country_origin),
        }),
      },
      market: {
        priceChangePct: omitUndefined({
          d24h: num(md?.price_change_percentage_24h),
          d7d: num(md?.price_change_percentage_7d),
          d30d: num(md?.price_change_percentage_30d),
          d1y: num(md?.price_change_percentage_1y),
        }),
        ...omitUndefined({
          currentPrice: pickCurrency(md?.current_price, currency),
          marketCap: pickCurrency(md?.market_cap, currency),
          fullyDilutedValuation: pickCurrency(md?.fully_diluted_valuation, currency),
          circulatingSupply: num(md?.circulating_supply),
          totalSupply: num(md?.total_supply),
          maxSupply: num(md?.max_supply),
          ath:
            athPrice !== undefined
              ? { price: athPrice, ...omitUndefined({ date: athDate }) }
              : undefined,
          atl:
            atlPrice !== undefined
              ? { price: atlPrice, ...omitUndefined({ date: atlDate }) }
              : undefined,
        }),
      },
      links: {
        homepage,
        repos,
        ...omitUndefined({
          whitepaper: str(links?.whitepaper),
          subreddit: str(links?.subreddit_url),
          twitter: str(links?.twitter_screen_name),
          telegram: str(links?.telegram_channel_identifier),
        }),
      },
      developer: omitUndefined({
        stars: num(dev?.stars),
        forks: num(dev?.forks),
        commits4w: num(dev?.commit_count_4_weeks),
        totalIssues: num(dev?.total_issues),
        closedIssues: num(dev?.closed_issues),
      }),
      community: omitUndefined({
        redditSubscribers: num(comm?.reddit_subscribers),
      }),
      sentiment: omitUndefined({
        upPercentage: num(raw.sentiment_votes_up_percentage),
        downPercentage: num(raw.sentiment_votes_down_percentage),
      }),
    };
  }

  /**
   * `/coins/{id}/market_chart` (recent) or `/market_chart/range` (explicit). Both
   * return `null` on 404. Timestamps are MILLISECONDS.
   */
  async marketChart(
    id: string,
    vsCurrency: string,
    days: number | 'max',
    ctx: Context,
  ): Promise<MarketChartResult | null> {
    const raw = await this.retry('coingecko.marketChart', ctx, () =>
      this.client.getJsonOrNull<RawMarketChart>(
        'coingecko.marketChart',
        `/coins/${encodeURIComponent(id)}/market_chart`,
        { vs_currency: vsCurrency, days: String(days) },
        ctx.signal,
      ),
    );
    return raw ? this.toChart(raw) : null;
  }

  async marketChartRange(
    id: string,
    vsCurrency: string,
    from: number,
    to: number,
    ctx: Context,
  ): Promise<MarketChartResult | null> {
    const raw = await this.retry('coingecko.marketChartRange', ctx, () =>
      this.client.getJsonOrNull<RawMarketChart>(
        'coingecko.marketChartRange',
        `/coins/${encodeURIComponent(id)}/market_chart/range`,
        { vs_currency: vsCurrency, from, to },
        ctx.signal,
      ),
    );
    return raw ? this.toChart(raw) : null;
  }

  private toChart(raw: RawMarketChart): MarketChartResult {
    return {
      prices: toPoints(raw.prices),
      marketCaps: toPoints(raw.market_caps),
      volumes: toPoints(raw.total_volumes),
    };
  }

  /** `/search/trending` — surfaces only trustworthy numerics (price float + USD 24h change). */
  async trending(ctx: Context): Promise<TrendingResult> {
    const raw = await this.retry('coingecko.trending', ctx, () =>
      this.client.getJson<RawTrendingResponse>(
        'coingecko.trending',
        '/search/trending',
        undefined,
        ctx.signal,
      ),
    );
    const coins = (raw.coins ?? []).map(({ item }) => ({
      id: item.id,
      name: item.name,
      symbol: item.symbol,
      ...omitUndefined({
        marketCapRank: typeof item.market_cap_rank === 'number' ? item.market_cap_rank : undefined,
        priceUsd: typeof item.data?.price === 'number' ? item.data.price : undefined,
        priceBtc: typeof item.price_btc === 'number' ? item.price_btc : undefined,
        priceChangePercentage24hUsd:
          typeof item.data?.price_change_percentage_24h?.usd === 'number'
            ? item.data.price_change_percentage_24h.usd
            : undefined,
      }),
    }));
    return { coins, nftCount: (raw.nfts ?? []).length };
  }

  /**
   * `/global` — macro snapshot. `currency` selects the dict key for cap/volume.
   * Unlike most endpoints, `/global` has no `vs_currency` param — it returns every
   * supported currency and the key is selected client-side, so an unsupported
   * currency is NOT rejected upstream. Throws a typed `unsupported_currency`
   * (NotFound) when the requested key is absent rather than fabricating a
   * `0` total (which would misreport the entire market as worthless).
   */
  async global(currency: string, ctx: Context): Promise<GlobalMarket> {
    const raw = await this.retry('coingecko.global', ctx, () =>
      this.client.getJson<RawGlobalResponse>('coingecko.global', '/global', undefined, ctx.signal),
    );
    const d = raw.data ?? {};
    const totalMarketCap = d.total_market_cap?.[currency];
    if (typeof totalMarketCap !== 'number') {
      throw notFound(`CoinGecko does not report global totals in "${currency}".`, {
        reason: 'unsupported_currency',
        currency,
        recovery: {
          hint: 'Use a supported currency code (e.g. "usd", "eur", "btc"). /global has no vs_currency validation, so an unknown code yields no totals.',
        },
      });
    }
    return {
      totalMarketCap,
      totalVolume24h: d.total_volume?.[currency] ?? 0,
      btcDominance: d.market_cap_percentage?.btc ?? 0,
      ethDominance: d.market_cap_percentage?.eth ?? 0,
      activeCryptocurrencies: d.active_cryptocurrencies ?? 0,
      markets: d.markets ?? 0,
      ongoingIcos: d.ongoing_icos ?? 0,
      marketCapChangePercentage24h: d.market_cap_change_percentage_24h_usd ?? 0,
      volumeChangePercentage24h: d.volume_change_percentage_24h_usd ?? 0,
      updatedAtUnixSec: d.updated_at ?? 0,
    };
  }

  /** `/coins/categories/list` — full bounded list (the tool filters locally). */
  async categoriesList(ctx: Context): Promise<Category[]> {
    const raw = await this.retry('coingecko.categoriesList', ctx, () =>
      this.client.getJson<RawCategory[]>(
        'coingecko.categoriesList',
        '/coins/categories/list',
        undefined,
        ctx.signal,
      ),
    );
    return raw.map((c) => ({ categoryId: c.category_id, name: c.name }));
  }
}

// ─── Init / Accessor ────────────────────────────────────────────────────────

let _service: CoinGeckoService | undefined;

/** Initialize the CoinGecko service. Call from `setup()` in createApp. */
export function initCoinGeckoService(): void {
  const config = getServerConfig();
  const client = new CoinGeckoApiClient({
    timeoutMs: TIMEOUT_MS,
    ...(config.apiKey && { apiKey: config.apiKey }),
  });
  _service = new CoinGeckoService(client);
  logger.info(
    'CoinGecko service initialized.',
    requestContextService.createRequestContext({
      operation: 'CoinGeckoInit',
      additionalContext: { hasApiKey: !!config.apiKey, timeoutMs: TIMEOUT_MS },
    }),
  );
}

/** Get the initialized CoinGecko service. Throws if not initialized. */
export function getCoinGeckoService(): CoinGeckoService {
  if (!_service) {
    throw new Error('CoinGecko service not initialized — call initCoinGeckoService() in setup().');
  }
  return _service;
}

/**
 * @fileoverview Service-layer failure modes the CoinGecko service can surface,
 * plus a `recoveryFor` resolver. Service code can't reach `ctx.recoveryFor` (no
 * Context), so it spreads `recoveryFor(reason)` into the error factory's `data`
 * arg — the framework mirrors `data.recovery.hint` into the wire payload's
 * `content[]` text, so clients get the same actionable hint a handler-level
 * `ctx.fail` would carry.
 *
 * These three reasons are upstream/transport failures shared across every tool
 * that calls the service. Domain-specific reasons (coin_not_found, all_missing,
 * unknown_category, invalid_range) are declared inline on the individual tools.
 * @module src/services/coingecko/error-contracts
 */

import { JsonRpcErrorCode } from '@cyanheads/mcp-ts-core/errors';

/**
 * Failure modes the CoinGecko service layer surfaces. Tools spread these into
 * their own `errors[]` so the declared contract matches what reaches the wire.
 */
export const COINGECKO_SERVICE_ERRORS = [
  {
    reason: 'rate_limited',
    code: JsonRpcErrorCode.RateLimited,
    when: 'CoinGecko returned HTTP 429 — the shared keyless pool is throttled, or the Demo-tier quota was hit.',
    recovery:
      'Wait a few seconds and retry; set COINGECKO_API_KEY for a higher rate ceiling on bursty workflows.',
    retryable: true,
  },
  {
    reason: 'upstream_unreachable',
    code: JsonRpcErrorCode.ServiceUnavailable,
    when: 'CoinGecko was unreachable or returned a 5xx/HTML error after all retry attempts.',
    recovery: 'Retry after a brief delay; CoinGecko was unreachable across all retry attempts.',
    retryable: true,
  },
  {
    reason: 'invalid_response',
    code: JsonRpcErrorCode.SerializationError,
    when: 'CoinGecko returned a body that could not be parsed as JSON.',
    recovery:
      'Retry the request; CoinGecko returned a malformed response that could not be parsed.',
    retryable: true,
  },
] as const;

export type CoinGeckoServiceReason = (typeof COINGECKO_SERVICE_ERRORS)[number]['reason'];

const REASON_TO_RECOVERY = new Map<CoinGeckoServiceReason, string>(
  COINGECKO_SERVICE_ERRORS.map((entry) => [entry.reason, entry.recovery]),
);

/**
 * Service-layer counterpart to `ctx.recoveryFor`. Returns `{ recovery: { hint } }`
 * for the contract reason, spread into the error factory's `data` so the wire
 * payload carries the same hint a handler-level `ctx.fail` would.
 *
 * @example
 *   throw serviceUnavailable(msg, { reason: 'upstream_unreachable', ...recoveryFor('upstream_unreachable') });
 */
export function recoveryFor(reason: CoinGeckoServiceReason): { recovery: { hint: string } } {
  const hint = REASON_TO_RECOVERY.get(reason);
  if (hint === undefined) {
    throw new Error(`recoveryFor: no recovery hint registered for reason "${reason}"`);
  }
  return { recovery: { hint } };
}

/**
 * @fileoverview Domain types for the CoinGecko REST API v3 service. Raw types
 * mirror probe-verified upstream response shapes (see docs/api-probe-notes.md);
 * normalized domain types are what the service hands tools. Upstream is sparse —
 * most nested fields are optional/nullable and are preserved as "unknown" rather
 * than fabricated when absent.
 * @module src/services/coingecko/types
 */

/** Keyless and Demo-tier share this base. (Pro switches the root — out of scope.) */
