  t: number;
  value: number;
}

export type ChartGranularity = 'minutely' | 'hourly' | 'daily';

export interface MarketChartResult {
  marketCaps: ChartPoint[];
  prices: ChartPoint[];
  volumes: ChartPoint[];
}

export interface Category {
  categoryId: string;
  name: string;
}

