// makeAPIRequest forwards a request to the CryptoMinute REST API.
func (s *MCPServer) makeAPIRequest(ctx context.Context, endpoint string, params url.Values) (interface{}, error) {
	apiBase := getEnvOrDefault("CM_API_BASE", "https://api.cryptominute.com")
	fullURL := apiBase + endpoint
	if len(params) > 0 {
		fullURL += "?" + params.Encode()
	}

	req, err := http.NewRequestWithContext(ctx, "GET", fullURL, nil)
	if err != nil {
		return nil, fmt.Errorf("create request: %w", err)
	}
	req.Header.Set("User-Agent", "CryptoMinute-MCP/1.0")
	req.Header.Set("Accept", "application/json")

	client := &http.Client{Timeout: 30 * time.Second}
	resp, err := client.Do(req)
	if err != nil {
		return nil, fmt.Errorf("API request failed: %w", err)
	}
	defer resp.Body.Close()

	if resp.StatusCode != http.StatusOK {
		return nil, fmt.Errorf("API returned status %d", resp.StatusCode)
	}

	var result interface{}
	if err := json.NewDecoder(resp.Body).Decode(&result); err != nil {
		return nil, fmt.Errorf("decode response: %w", err)
	}

	jsonData, err := json.Marshal(result)
	if err != nil {
		return nil, fmt.Errorf("marshal response: %w", err)
	}
	return string(jsonData), nil
}

// Parameter helpers

func setString(params url.Values, args map[string]interface{}, argKey, paramKey string) {
	if v, ok := args[argKey].(string); ok && v != "" {
		params.Set(paramKey, v)
	}
}

func setAny(params url.Values, args map[string]interface{}, argKey, paramKey string) {
	if v, ok := args[argKey]; ok {
		params.Set(paramKey, fmt.Sprintf("%v", v))
	}
}

func setBool(params url.Values, args map[string]interface{}, argKey, paramKey string) {
	if v, ok := args[argKey].(bool); ok {
		params.Set(paramKey, strconv.FormatBool(v))
	}
}

