package main

import (
	"context"
	"embed"
	"encoding/json"
	"fmt"
	"log/slog"
	"net/http"
	"os"
	"strings"
	"time"
)

//go:embed schemas/*.json
var schemasFS embed.FS

// MCPServer represents the Model Context Protocol server.
type MCPServer struct {
	tools       map[string]*Tool
	rateLimiter *RateLimiter
}

// Tool represents an MCP tool with its metadata and handler.
type Tool struct {
	Name        string                 `json:"name"`
	Description string                 `json:"description"`
	InputSchema map[string]interface{} `json:"inputSchema"`
	Handler     ToolHandler            `json:"-"`
}

// ToolHandler is the function signature for tool execution.
type ToolHandler func(ctx context.Context, args map[string]interface{}) (interface{}, error)

// MCP protocol types

type MCPRequest struct {
	Jsonrpc string                 `json:"jsonrpc"`
	ID      interface{}            `json:"id"`
	Method  string                 `json:"method"`
	Params  map[string]interface{} `json:"params,omitempty"`
}

type MCPResponse struct {
	Jsonrpc string      `json:"jsonrpc"`
	ID      interface{} `json:"id"`
	Result  interface{} `json:"result,omitempty"`
	Error   *MCPError   `json:"error,omitempty"`
}

type MCPError struct {
	Code    int         `json:"code"`
	Message string      `json:"message"`
	Data    interface{} `json:"data,omitempty"`
}

// RateLimiter implements token bucket rate limiting.
type RateLimiter struct {
	tokens     int
	maxTokens  int
	refillRate int
	lastRefill time.Time
}

func NewRateLimiter(maxTokens, refillRate int) *RateLimiter {
	return &RateLimiter{
		tokens:     maxTokens,
		maxTokens:  maxTokens,
		refillRate: refillRate,
		lastRefill: time.Now(),
	}
}

func (rl *RateLimiter) Allow() bool {
	now := time.Now()
	elapsed := now.Sub(rl.lastRefill)
	tokensToAdd := int(elapsed.Seconds()) * rl.refillRate
	if tokensToAdd > 0 {
		rl.tokens = min(rl.maxTokens, rl.tokens+tokensToAdd)
		rl.lastRefill = now
	}
	if rl.tokens > 0 {
		rl.tokens--
		return true
	}
	return false
}

// NewServer creates a new MCP server with all tools registered.
func NewServer() *MCPServer {
	server := &MCPServer{
		tools:       make(map[string]*Tool),
		rateLimiter: NewRateLimiter(60, 1), // 60 req/s burst, 1 token/s refill
	}
	server.registerTools()
	return server
}

func (s *MCPServer) registerTools() {
	tools := []struct {
		name        string
		description string
		handler     ToolHandler
	}{
		{"crypto-news-search", "Filter news by ticker, sentiment, date, significance", s.handleCryptoNewsSearch},
		{"crypto-analytics", "Five-dimensional narrative analytics", s.handleCryptoAnalytics},
		{"crypto-stories", "AI-clustered narrative summaries", s.handleCryptoStories},
		{"crypto-reddit-monitor", "Reddit sentiment & impact", s.handleCryptoRedditMonitor},
		{"crypto-youtube-insights", "Video engagement metrics", s.handleCryptoYouTubeInsights},
		{"crypto-prices", "Historical OHLCV data", s.handleCryptoPrices},
		{"crypto-tokens", "Token metadata & categorization", s.handleCryptoTokens},
		{"crypto-flash-posts", "Real-time flash posts from cryptocurrency Telegram channels", s.handleCryptoFlashPosts},
	}

	for _, t := range tools {
		schema, err := s.loadSchema(t.name)
		if err != nil {
			slog.Error("Failed to load schema", "tool", t.name, "error", err)
			continue
		}
		s.tools[t.name] = &Tool{
			Name:        t.name,
			Description: t.description,
			InputSchema: schema,
			Handler:     t.handler,
		}
		slog.Info("Registered tool", "name", t.name)
	}
}

func (s *MCPServer) loadSchema(toolName string) (map[string]interface{}, error) {
	data, err := schemasFS.ReadFile("schemas/" + toolName + ".json")
	if err != nil {
		return map[string]interface{}{"type": "object", "properties": map[string]interface{}{}}, nil
	}
	var schema map[string]interface{}
	if err := json.Unmarshal(data, &schema); err != nil {
		return nil, fmt.Errorf("parse schema %s: %w", toolName, err)
	}
	return schema, nil
}

// ServeHTTP starts the MCP server with HTTP transport.
func (s *MCPServer) ServeHTTP(ctx context.Context, addr string) error {
	mux := http.NewServeMux()
	mux.HandleFunc("/metrics", s.handleMetrics)
	mux.HandleFunc("/health", s.handleHealth)
	mux.HandleFunc("/", s.handleMCPRequest)

	server := &http.Server{Addr: addr, Handler: mux}

	go func() {
		slog.Info("MCP HTTP server listening", "addr", addr)
		if err := server.ListenAndServe(); err != nil && err != http.ErrServerClosed {
			slog.Error("HTTP server error", "error", err)
		}
	}()

	<-ctx.Done()
	shutdownCtx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()
	return server.Shutdown(shutdownCtx)
}

// ServeStdio starts the MCP server with stdio transport.
func (s *MCPServer) ServeStdio(ctx context.Context) error {
	slog.Info("MCP stdio server ready")
	decoder := json.NewDecoder(os.Stdin)
	encoder := json.NewEncoder(os.Stdout)

	for {
		select {
		case <-ctx.Done():
			return nil
		default:
			var request MCPRequest
			if err := decoder.Decode(&request); err != nil {
				continue
			}
			response := s.processRequest(ctx, &request)
			if err := encoder.Encode(response); err != nil {
				slog.Error("Failed to encode response", "error", err)
			}
		}
	}
}

func (s *MCPServer) handleMCPRequest(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Access-Control-Allow-Origin", "*")
	w.Header().Set("Access-Control-Allow-Methods", "POST, OPTIONS")
	w.Header().Set("Access-Control-Allow-Headers", "Content-Type, Authorization")

	if r.Method == http.MethodOptions {
		w.WriteHeader(http.StatusOK)
		return
	}

	if !s.rateLimiter.Allow() {
		http.Error(w, "Rate limit exceeded", http.StatusTooManyRequests)
		return
	}

	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	var request MCPRequest
	if err := json.NewDecoder(r.Body).Decode(&request); err != nil {
		http.Error(w, "Invalid JSON", http.StatusBadRequest)
		return
	}

	response := s.processRequest(r.Context(), &request)
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(response)
}

func (s *MCPServer) processRequest(ctx context.Context, req *MCPRequest) *MCPResponse {
	resp := &MCPResponse{Jsonrpc: "2.0", ID: req.ID}

	switch req.Method {
	case "initialize":
		resp.Result = map[string]interface{}{
			"protocolVersion": "2024-11-05",
			"capabilities": map[string]interface{}{
				"tools":   map[string]interface{}{"listChanged": false},
				"logging": map[string]interface{}{},
			},
			"serverInfo": map[string]interface{}{
				"name":    "cryptominute-news-mcp",
				"version": "1.0.0",
			},
		}
	case "tools/list":
		resp.Result = s.listTools()
	case "tools/call":
		result, err := s.callTool(ctx, req.Params)
		if err != nil {
			resp.Error = &MCPError{Code: -32000, Message: err.Error()}
		} else {
			resp.Result = result
		}
	case "ping":
		resp.Result = map[string]interface{}{"pong": true}
	case "notifications/initialized":
		resp.Result = map[string]interface{}{"success": true}
	default:
		resp.Error = &MCPError{Code: -32601, Message: "Method not found"}
	}

	return resp
}

func (s *MCPServer) listTools() interface{} {
	tools := make([]Tool, 0, len(s.tools))
	for _, t := range s.tools {
		tools = append(tools, Tool{Name: t.Name, Description: t.Description, InputSchema: t.InputSchema})
	}
	return map[string]interface{}{"tools": tools}
}

func (s *MCPServer) callTool(ctx context.Context, params map[string]interface{}) (interface{}, error) {
	name, _ := params["name"].(string)
	if name == "" {
		return nil, fmt.Errorf("missing tool name")
	}

	tool, ok := s.tools[name]
	if !ok {
		return nil, fmt.Errorf("tool not found: %s", name)
	}

	args, _ := params["arguments"].(map[string]interface{})
	if args == nil {
		args = map[string]interface{}{}
	}

	if err := validateArgs(args, tool.InputSchema); err != nil {
		return nil, fmt.Errorf("validation: %w", err)
	}

	result, err := tool.Handler(ctx, args)
	if err != nil {
		return nil, err
	}

	return map[string]interface{}{
		"content": []map[string]interface{}{{"type": "text", "text": result}},
	}, nil
}

func (s *MCPServer) handleHealth(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Access-Control-Allow-Origin", "*")
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(map[string]interface{}{
		"status":    "healthy",
		"timestamp": time.Now().UTC().Format(time.RFC3339),
		"tools":     len(s.tools),
	})
}

func (s *MCPServer) handleMetrics(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "text/plain")
	fmt.Fprintf(w, "# HELP mcp_tools_registered Number of registered tools\n")
	fmt.Fprintf(w, "# TYPE mcp_tools_registered gauge\n")
	fmt.Fprintf(w, "mcp_tools_registered %d\n", len(s.tools))
}

func getEnvOrDefault(key, defaultValue string) string {
	if v := strings.TrimSpace(os.Getenv(key)); v != "" {
		return v
	}
	return defaultValue
}

